// validateNoDuplicateUTXOs ensures the given UTXO list is non-empty and
// contains no duplicate outpoints. It is shared by the different input
// validation routines to avoid duplicating this logic.
func validateNoDuplicateUTXOs(utxos []wire.OutPoint) error {
	if len(utxos) == 0 {
		return ErrManualInputsEmpty
	}

	// Make sure there are no duplicates in the specified UTXO list.
	seenUTXOs := make(map[wire.OutPoint]struct{})
	for _, utxo := range utxos {
		if _, ok := seenUTXOs[utxo]; ok {
			return ErrDuplicatedUtxo
		}

		seenUTXOs[utxo] = struct{}{}
	}

	return nil
}

// validate performs validation on the manual inputs.
func (i *InputsManual) validate() error {
	return validateNoDuplicateUTXOs(i.UTXOs)
}

// If the source is a list of UTXOs, it must not be empty and
// must not contain duplicates.
case *CoinSourceUTXOs:
	if err := validateNoDuplicateUTXOs(source.UTXOs); err != nil {
		return err
	}

